import { BooleanColumn, Table, StringColumn, ReferenceColumn } from '../../db'

export const sys_ux_app_config = Table({
    name: 'sys_ux_app_config',
    schema: {
        name: StringColumn({ mandatory: true }),
        sys_name: StringColumn({}),
        active: BooleanColumn({}),
        disable_auto_reflow: BooleanColumn({}),
        encode_query_string: BooleanColumn({}),
        default_route_type: StringColumn({}),
        icon: ReferenceColumn({ referenceTable: 'st_sys_design_system_icon' }),
        description: StringColumn({}),
        landing_path: StringColumn({}),
        base_url_path: StringColumn({}),
    },
})
